import { expect, test, uniqueName, type APIRequestContext } from "../../fixtures";

const LOW_INSURANCE = "Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: next spring\n";
const GOOD_INSURANCE = "Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: 2027-03-31\n";

async function inReviewVendor(member: APIRequestContext, name: string, insurance: string): Promise<{ id: string }> {
  const created = await member.post("/api/vendors", {
    data: { name, category: "services", contact_email: "ops@example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const documents: Record<string, string> = {
    w9: `Legal Name: ${name}\nTax ID: 84-2219067\nBusiness Type: LLC\n`,
    insurance_certificate: insurance,
    contract: "Counterparty: Harborline Logistics LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n",
  };
  for (const [kind, text] of Object.entries(documents)) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind, file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) } },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  await expect
    .poll(
      async () => {
        const list = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await list.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);
  return vendor;
}

test("The review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const low = await inReviewVendor(member, uniqueName("Shaky Vendor"), LOW_INSURANCE);
  const high = await inReviewVendor(member, uniqueName("Confident Vendor"), GOOD_INSURANCE);

  // Act
  const response = await reviewer.get("/api/review-queue");

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const queue = (await response.json()) as { vendor_id: string; lowest_confidence: number }[];
  // Other tests share the database, so only compare the two vendors this test created.
  const ours = queue.filter((item) => item.vendor_id === low.id || item.vendor_id === high.id);
  expect(ours.map((item) => item.vendor_id)).toEqual([low.id, high.id]);
  expect(ours[0].lowest_confidence).toBe(0.4);
  expect(ours[1].lowest_confidence).toBe(0.95);
});
